    "rb.t.overview": "Overview", "rb.t.where": "Where views come from", "rb.wk.up": "▲ {p}% vs {n} at this point last week", "rb.wk.down": "▼ {p}% vs {n} at this point last week", "rb.wk.foot": "Posts out in the last 7 days; last week counted at the same point", "rb.wk.def": "Views so far on the posts that went out in the last 7 days, against what the posts of the 7 days before had at this same point last week. New posts keep gaining views for days, so like is compared with like. Replaced or deleted uploads are not counted. Reels › Today shows the same number.", "rb.make": "Make a reel like this", "rb.made.try": "Make reels is open with this suggestion kept: {what}. Pick a theme, then Make. Nothing is made or booked until you press it.", "rb.made.test": "Make reels is open for the test: {what}. Make two reels of one theme, then book them at the same hour on two days next to each other.", "rb.test.hookw": "one headline opening with 「{p}」, one without", "rb.test.lenw": "one cut of {s} s or less, one longer", "rb.test.hookwhy": "Test whether openings with 「{p}」 really get more views.", "rb.test.lenwhy": "Test whether a cut of {s} s or less is watched further.", "rb.test.h": "Set up this test", "rb.test.sub": "two reels alike but for one thing, at the same hour", "rb.test.s1": "Make two reels from one theme (Make reels opens with this test noted).", "rb.test.hook2": "Give one a first line with 「{p}」 and the other a first line without it (Words, or the reel's headline).", "rb.test.len2": "Keep one at {s} s or less and let the other run longer (the reel's length in the editor).", "rb.test.s3": "Book both at the same hour on two days next to each other (Posting › Week).", "rb.test.read": "About 3 days after the second one goes out, compare them in Every post. Nothing here books by itself.", "rb.test.go": "Open Make reels for this test", "rb.test.week": "Posting › Week", "rb.does.model": "Plan posts breaks ties with this score only while it goes with views; otherwise with what the learned model expects.", "rb.does.worked": "Make reels can draw its looks and text layouts from this list when “Use what worked” is on.", "rb.exp.h": "Experiments running", "rb.exp.row": "Testing {h} on {net} against the usual {u}: {o} of {of} posts out, read about {d}.", "rb.exp.booked": "{n} more booked.", "rb.exp.early": "So far {r}× the usual hour ({n} posts).", "rb.exp.none": "No hour test is running: no booking sits at a network's other listed hour yet.", "rb.exp.does": "Booking by itself puts every {k}th post on a network with more than one listed hour at one of its other hours, as a test; posts booked there by hand count too (Settings › Accounts lists the hours).", "rb.wait": "{n} of {of} posts measured so far. Findings firm up at {of}; with the posts booked, that is around {when}.", "rb.waitnone": "{n} of {of} posts measured so far. Findings firm up at {of}; book more posts to get there.", "rb.allnext": "All suggestions, what worked, best time", "rb.outsum": "{n} posts out or booked, per network", "rb.pa.order": "Plan posts breaks ties between reels that fit a slot equally well (after the theme of the day and the fewest repeats). With a link this weak (rank {r}) the score would be close to random, so it uses what the learned model expects from each reel instead; the score takes over again from +0.3.", "rb.pa.ordernone": "Plan posts orders by this score until enough posts are measured to check it against views ({r}).", "rb.pa.orderok": "Plan posts uses this score to choose between reels that fit a slot equally well (after the theme of the day and the fewest repeats); rank {r} says it is starting to help.", "rb.f.overview": "Results overview", "rb.f.overviewsub": "This week's views, what the numbers say", "rb.f.trysub": "Results › What to try next", "rb.f.workedsub": "Results › What to try next: helped and held back", "rb.f.btsub": "Results › What to try next: day × hour", "rb.f.expsub": "Results › Best time: hour tests running", "rb.f.predsub": "Results › What to try next: score against views", "rb.f.wheresub": "Results: posts in, views out, per network", "rb.f.postssub": "Results: every post with its numbers", "rb.f.runssub": "Posting: the booking and checks the studio does by itself", "rb.f.looks": "Learned looks", "rb.f.lookssub": "Reels › Make reels: use what worked", "rb.f.loop": "The loop (plan, make, check, act)", "rb.f.loopsub": "Reels › Today", "rb.f.map": "Accounts map", "rb.f.mapsub": "Settings › Accounts", "rb.f.photossub": "Reels › Photo posts",
    "rb.rej.line": "Sent back in review, {d} days: {list}.", "rb.rej.looks": "Looks sent back most: {list}.", "rb.rej.tag": "look sent back {n}× in {d} days",
