/* English counts: "1 reels" reads "1 reel" (every label says {n} things; Japanese has no plural). */
const ONE = /(^|[^\d.,])1 (reel|clip|theme|post|file|line|network|photo|video|day|minute|second|thing|place|service|job)s\b/g;
const tr = (k, vars = {}) => {
  const t = String(I18N[lang][k] ?? I18N.en[k] ?? k).replace(/\{(\w+)\}/g, (_, v) => vars[v] ?? "");
  return lang === "en" ? t.replace(ONE, "$11 $2") : t;
};
function applyLang() {
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-t]").forEach((el) => { el.textContent = tr(el.dataset.t); });
  // On a phone "English" is shown as EN so the header keeps one row; the button still says English to a screen reader.
  $("#lang").innerHTML = lang === "en" ? `<span class="lfull">日本語</span><span class="lshort" aria-hidden="true">JA</span>` : `<span class="lfull">English</span><span class="lshort" aria-hidden="true">EN</span>`; $("#lang").setAttribute("aria-label", lang === "en" ? "日本語" : "English");
  $("#lang").setAttribute("aria-label", lang === "en" ? "日本語" : "English");
}
/* The whole page in the other language at once: the header toggle and the setup wizard both come here, so the page
   behind the wizard never stays in the old language. */
function setLang(next) {
  if (next === lang) return;
  lang = next; try { localStorage.setItem("studio.lang", lang); } catch { /* private window */ }
  applyLang();
  // Banners are written in the language of the moment: write them again in the new one.
  sys.msgs.clear(); $("#sysbar").innerHTML = ""; const wasDown = sys.down; sys.down = false; if (wasDown) sys.offline(true); else sys.check();
  setTitle(); if (atHome()) renderHome(true); else { renderLeft(); offerDraft(); }
  paintNews(); paintStatus();  // the bell and the status bar speak the new language at once, not at their next tick
  PROB.load();  // the problems strip too: each problem comes in both languages
}

